<?php
declare(strict_types=1);
return static function(Suite $t, PDO $pdo, array $fx):void {
    $fx=tdb_seed($pdo);$a=new Http('management_admin');$a->login('t_admin');$v=new Http('management_voter');$v->login('t_voter1');$anon=new Http('management_anon');
    $t->group('Branding permissions and database persistence');
    $t->same('public branding contains only display settings', ['text','logo','coopName'], array_keys($anon->api('GET','branding')['json']));
    $t->same('anonymous cannot save branding',401,$anon->api('PUT','branding',['text'=>'Other','logo'=>null])['status']);
    $t->same('voter cannot save branding',403,$v->api('PUT','branding',['text'=>'Other','logo'=>null])['status']);
    foreach (['', '   ', str_repeat('x',41)] as $name) $t->same('invalid brand text rejected',422,$a->api('PUT','branding',['text'=>$name,'logo'=>null])['status']);
    $t->same('SVG logo rejected',422,$a->api('PUT','branding',['text'=>'Coop','logo'=>'data:image/svg+xml;base64,'.base64_encode('<svg/>')])['status']);
    $t->same('fake raster rejected',422,$a->api('PUT','branding',['text'=>'Coop','logo'=>'data:image/png;base64,'.base64_encode('not an image')])['status']);
    $png=base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jB1sAAAAASUVORK5CYII=');
    $saved=$a->api('PUT','branding',['text'=>'Test Cooperative','logo'=>'data:image/png;base64,'.base64_encode($png)]);
    $t->same('admin saves logo and name',200,$saved['status']);
    $t->same('public view returns saved name','Test Cooperative',$anon->api('GET','branding')['json']['text']);
    $stored=json_decode($pdo->query("SELECT setting_value FROM settings WHERE setting_key='site_branding'")->fetchColumn(),true);
    $t->ok('logo stored as validated database image',preg_match('#^data:image/(png|webp);base64,#',$stored['logo']??'')===1);
    $t->same('default mark can be restored',200,$a->api('PUT','branding',['text'=>'CoopVote','logo'=>null])['status']);
    $t->same('removed image stays removed',null,$anon->api('GET','branding')['json']['logo']);
    foreach (['', '   ',str_repeat('x',151)] as $name) $t->same('invalid cooperative name rejected',422,$a->api('PUT','branding',['text'=>'CoopVote','logo'=>null,'coopName'=>$name])['status']);
    $t->same('cooperative name saves',200,$a->api('PUT','branding',['text'=>'CoopVote','logo'=>null,'coopName'=>'New Cooperative'])['status']);
    $t->same('cooperative name persists','New Cooperative',$anon->api('GET','branding')['json']['coopName']);
    $t->same('existing name setting stays in sync','New Cooperative',$pdo->query("SELECT setting_value FROM settings WHERE setting_key='coop_name'")->fetchColumn());
    $t->same('save complete default identity',200,$a->api('PUT','branding',['text'=>'CoopVote','logo'=>null,'coopName'=>'Santiago City Multi-Purpose Cooperative'])['status']);
    $defaults=$anon->api('GET','branding')['json'];
    $t->same('default logo text persists','CoopVote',$defaults['text']);
    $t->same('default cooperative name persists','Santiago City Multi-Purpose Cooperative',$defaults['coopName']);
    $t->same('default logo persists',null,$defaults['logo']);
    $t->group('Default theme restores branding atomically for administrators');
    $custom=['text'=>'Custom Mark','logo'=>'data:image/png;base64,'.base64_encode($png),'coopName'=>'Custom Cooperative'];
    $a->api('PUT','branding',$custom);
    $custom=$anon->api('GET','branding')['json'];
    $a->api('PUT','management/preferences',['theme'=>'forest']);
    $t->same('other themes retain the complete branding',$custom,$anon->api('GET','branding')['json']);
    $t->same('voter cannot request shared branding reset',403,$v->api('PUT','management/preferences',['theme'=>'navy','resetBranding'=>true])['status']);
    $t->same('voter default theme changes only their preference',200,$v->api('PUT','management/preferences',['theme'=>'navy'])['status']);
    $t->same('voter theme leaves branding intact',$custom,$anon->api('GET','branding')['json']);
    $t->same('non-default branding reset refused',422,$a->api('PUT','management/preferences',['theme'=>'light','resetBranding'=>true])['status']);
    $t->same('invalid reset flag refused',422,$a->api('PUT','management/preferences',['theme'=>'navy','resetBranding'=>'true'])['status']);
    tdb_guard((string)$pdo->query('SELECT DATABASE()')->fetchColumn());
    $pdo->exec("CREATE TRIGGER test_branding_reset_failure BEFORE UPDATE ON settings FOR EACH ROW BEGIN IF NEW.setting_key='coop_name' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Simulated branding write failure'; END IF; END");
    try {
        $t->same('failed branding write reports failure',500,$a->api('PUT','management/preferences',['theme'=>'navy','resetBranding'=>true])['status']);
        $t->same('failed reset rolls back theme','forest',$a->api('GET','management/preferences')['json']['theme']);
        $t->same('failed reset rolls back logo and text',$custom,$anon->api('GET','branding')['json']);
    } finally { $pdo->exec('DROP TRIGGER IF EXISTS test_branding_reset_failure'); }
    $reset=$a->api('PUT','management/preferences',['theme'=>'navy','resetBranding'=>true]);
    $t->same('default action saves successfully',200,$reset['status']);
    $t->same('default action returns saved branding',$defaults,$reset['json']['branding']);
    $t->same('default theme persists','navy',$a->api('GET','management/preferences')['json']['theme']);
    $a->api('PUT','branding',$custom);
    $t->same('already selected default can restore branding again',200,$a->api('PUT','management/preferences',['theme'=>'navy','resetBranding'=>true])['status']);
    $a->api('POST','auth/logout',[]);$a->login('t_admin');
    $t->same('default branding survives login',$defaults,$anon->api('GET','branding')['json']);
    $t->group('Account boundaries and persistent preferences');
    $t->same('anonymous cannot read preferences',401,$anon->api('GET','management/preferences')['status']);
    foreach(['accounts','overview'] as $route)$t->same('voter cannot read '.$route,403,$v->api('GET','management/'.$route)['status']);
    $t->same('voter cannot create admin',403,$v->api('POST','management/accounts',['name'=>'Officer Jane','username'=>'jane','email'=>'jane@test.coop'])['status']);
    $t->same('voter cannot change threshold',403,$v->api('PUT','management/config',['requiredApprovals'=>1])['status']);
    foreach(['navy','light','forest','ocean','plum','slate'] as $theme){
        $t->same('save '.$theme,200,$v->api('PUT','management/preferences',['theme'=>$theme,'userId'=>$fx['admin']])['status']);
        $t->same('read '.$theme,$theme,$v->api('GET','management/preferences')['json']['theme']);
    }
    $t->same('another account preference is unchanged','navy',$a->api('GET','management/preferences')['json']['theme']);
    $v->api('POST','auth/logout',[]);$v->login('t_voter1');
    $t->same('theme survives logout/login','slate',$v->api('GET','management/preferences')['json']['theme']);
    foreach(['',' ', 'evil', '<script>'] as $theme)$t->same('unsupported theme refused',422,$v->api('PUT','management/preferences',['theme'=>$theme])['status']);
    foreach([0,2,'bad'] as $n)$t->same('invalid threshold refused',422,$a->api('PUT','management/config',['requiredApprovals'=>$n])['status']);
    $t->same('self deactivation refused',409,$a->api('POST','management/accounts/'.$fx['admin'],['status'=>'deactivated'])['status']);
    $t->same('blank name refused',422,$a->api('POST','management/accounts',['name'=>' ','username'=>'officer','email'=>'officer@test.coop'])['status']);
    $t->same('name with numbers refused',422,$a->api('POST','management/accounts',['name'=>'Officer 1','username'=>'officer','email'=>'officer@test.coop'])['status']);
    $body=['name'=>'Officer Jane','username'=>'officer.jane','email'=>'officer.jane@test.coop'];
    $created=$a->api('POST','management/accounts',$body);$t->same('admin account created',201,$created['status']);
    $t->same('duplicate username refused',409,$a->api('POST','management/accounts',$body)['status']);
    $row=$pdo->query("SELECT u.*,r.slug FROM users u JOIN roles r ON r.role_id=u.role_id WHERE username='officer.jane'")->fetch();$id=(int)$row['user_id'];
    $t->same('officer uses existing admin role','admin',$row['slug']);$t->same('exactly two roles remain',2,(int)$pdo->query('SELECT COUNT(*) FROM roles')->fetchColumn());
    $t->ok('generated password is hashed',password_verify($created['json']['password'],$row['password_hash']));
    $b=new Http('management_second');$t->same('officer can log in',200,$b->login('officer.jane',$created['json']['password'])['status']);
    $t->same('officer details editable',200,$a->api('PUT','management/accounts/'.$id,['name'=>'Jane Santos','email'=>'jane.santos@test.coop'])['status']);
    $t->same('empty edit is refused',422,$a->api('PUT','management/accounts/'.$id,['name'=>'','email'=>''])['status']);
    $t->same('two approvals can be configured',200,$a->api('PUT','management/config',['requiredApprovals'=>2])['status']);
    $t->same('cannot leave too few admins',409,$a->api('POST','management/accounts/'.$id,['status'=>'deactivated'])['status']);

    $t->group('Distinct admin approval gate and stale snapshots');
    $eid=$fx['draft'];$route='elections/'.$eid.'/activate';
    $t->same('activation requires approval',409,$a->api('PATCH',$route,[])['status']);
    $t->same('publish alias cannot bypass',409,$a->api('PATCH','elections/'.$eid.'/publish',[])['status']);
    $t->same('voter cannot submit election',403,$v->api('POST','management/elections/'.$eid.'/submit',[])['status']);
    $submit=fn()=>$a->api('POST','management/elections/'.$eid.'/submit',[]);
    $request=static function()use($a,$eid){foreach($a->api('GET','management/overview')['json']['elections'] as $e)if($e['id']===$eid)return $e['request'];return null;};
    // The seed draft has no candidates; add one using the real nomination API.
    $p=$pdo->query('SELECT position_id FROM positions WHERE election_id='.$eid.' LIMIT 1')->fetchColumn();
    if(!$p)$p=$a->api('POST','positions',['electionId'=>$eid,'name'=>'Chairperson'])['json']['id'];
    $a->api('POST','candidates',['electionId'=>$eid,'positionId'=>(int)$p,'memberId'=>$fx['standing']['Chairperson'][1]['member']]);
    $t->same('request submitted',200,$submit()['status']);$r=$request();
    $t->same('snapshot fixes threshold',2,(int)$r['required_approvals']);
    $t->same('voter cannot decide',403,$v->api('POST','management/elections/'.$eid.'/decide',['requestId'=>$r['request_id'],'decision'=>'approve'])['status']);
    $decide=fn($client,$r,$d='approve',$note='')=>$client->api('POST','management/elections/'.$eid.'/decide',['requestId'=>$r['request_id'],'decision'=>$d,'note'=>$note]);
    $t->same('first approval recorded',200,$decide($a,$r)['status']);
    $t->same('same admin cannot count twice',409,$decide($a,$r)['status']);
    $t->same('one of two cannot open',409,$a->api('PATCH',$route,[])['status']);
    $submit();$t->same('duplicate submit keeps approvals',1,$request()['approvals']);
    $a->api('PUT','management/config',['requiredApprovals'=>1]);$t->same('config change does not weaken pending request',2,(int)$request()['required_approvals']);$a->api('PUT','management/config',['requiredApprovals'=>2]);
    $t->same('second distinct approval recorded',200,$decide($b,$r)['status']);
    $pdo->exec("UPDATE elections SET title='Changed review title' WHERE election_id=$eid");
    $t->same('changed election cannot open',409,$a->api('PATCH',$route,[])['status']);
    $t->ok('request reports stale state',$request()['stale']);
    $submit();$new=$request();$t->ok('resubmission has new ID',$new['request_id']!==$r['request_id']);
    $t->same('old request cannot receive approval',409,$decide($b,$r)['status']);
    $t->same('reject requires reason',422,$decide($b,$new,'reject',' ')['status']);
    $t->same('rejection recorded',200,$decide($b,$new,'reject','Check the candidate platform.')['status']);
    $t->same('rejection blocks opening',409,$a->api('PATCH',$route,[])['status']);
    $submit();$new=$request();$decide($a,$new);$decide($b,$new);
    $pdo->exec("UPDATE candidates SET platform='Updated platform' WHERE election_id=$eid");
    $t->same('changed candidate invalidates approval',409,$a->api('PATCH',$route,[])['status']);
    $submit();$new=$request();$decide($a,$new);$decide($b,$new);
    $t->same('fully approved election opens',200,$a->api('PATCH',$route,[])['status']);
    $t->same('consumed request no longer pending',null,$request());
    $t->same('opening again is idempotent',200,$a->api('PATCH',$route,[])['status']);
    $t->same('closing still works',200,$a->api('PATCH','elections/'.$eid.'/close',[])['status']);
    $end=date('Y-m-d\TH:i',time()+86400);
    $t->same('old approvals cannot reopen',409,$a->api('PATCH','elections/'.$eid.'/reopen',['endDate'=>$end])['status']);
    $a->api('POST','management/elections/'.$eid.'/submit',['proposedEnd'=>$end]);$r=$request();$decide($a,$r);$decide($b,$r);
    $t->same('unapproved reopening deadline refused',409,$a->api('PATCH','elections/'.$eid.'/reopen',['endDate'=>date('Y-m-d\TH:i',time()+172800)])['status']);
    $t->same('approved deadline reopens',200,$a->api('PATCH','elections/'.$eid.'/reopen',['endDate'=>$end])['status']);
    $a->api('PUT','management/config',['requiredApprovals'=>1]);
    $t->same('officer can be deactivated when coverage allows',200,$a->api('POST','management/accounts/'.$id,['status'=>'deactivated'])['status']);
    $t->same('existing session loses admin access when deactivated',403,$b->api('GET','management/overview')['status']);
    $t->same('officer can be activated again',200,$a->api('POST','management/accounts/'.$id,['status'=>'active'])['status']);
};
